('MI_ENTITIES_IN_SCOPE','Entities in supervisory scope','The number of regulated entities that fall inside the sectors the viewer is authorised to supervise. This is the denominator for every coverage measure.','population','licensees','Count of licensees',NULL,'Licensee records in an authorised sector','Entities in sectors outside the viewer''s remit','point_in_time','{sector}','Reported as at the report date, not the period end.',10),
('MI_ENTITIES_WITH_ATTENTION','Entities under supervisory attention','Entities named on at least one open supervisory attention item.','population','licensees via conduct_attention_items','Count of licensees with an open attention item','MI_ENTITIES_IN_SCOPE','Licensee appears in the entity list of an attention item not yet closed','Closed attention items','point_in_time','{sector}','An entity is counted once regardless of how many attention items name it.',11),
('MI_ENTITIES_WITH_ACTIVE_PLAN','Entities covered by a supervisory plan','Entities named on an approved or active supervisory plan.','population','licensees via conduct_supervisory_plans','Count of licensees on an approved or active plan','MI_ENTITIES_IN_SCOPE','Plan status is approved or active','Draft, submitted, completed or cancelled plans','point_in_time','{sector}',NULL,12),
('MI_ENTITIES_WITH_INTERVENTION','Entities under active intervention','Entities that are the subject of an endorsed or active supervisory intervention.','population','licensees via conduct_interventions','Count of licensees with an endorsed or active intervention','MI_ENTITIES_IN_SCOPE','Intervention status is endorsed or active and names the entity','Proposed, rejected, completed or cancelled interventions','point_in_time','{sector}',NULL,13),
('MI_ENTITIES_IN_EMERGING_RISK','Entities linked to an emerging risk','Entities named on an open attention item that originated from an emerging risk.','population','licensees via conduct_attention_items','Count of licensees on an open emerging-risk-sourced attention item','MI_ENTITIES_IN_SCOPE','Attention item is linked to an emerging risk and is not closed','Attention items with no emerging risk link','point_in_time','{sector}',NULL,14),
