('MI_RISK_ASSESSING','Emerging risks under assessment','Emerging risks currently being assessed by a supervisor.','emerging_risk','conduct_emerging_risks','Count of emerging risks with status assessing',NULL,'Status is assessing','All other statuses','point_in_time','{sector,severity}',NULL,21),
('MI_RISK_CONFIRMED','Emerging risks confirmed','Emerging risks a supervisor has confirmed as real.','emerging_risk','conduct_emerging_risks','Count of emerging risks with status confirmed',NULL,'Status is confirmed','Dismissed, monitoring and closed risks','point_in_time','{sector,severity}',NULL,22),
