INSERT INTO public.release_debt_register
 (item_code, test_reference, assertion, title, classification, description,
  security_blocking, release_blocking, owner_role, raised_in_phase, target_phase, intended_verification)
VALUES
('RD-001','rbac/100_prudential_rls','22','Prudential supervision table exposure assertion fails','DATA_API_GRANT','A prudential supervision table assertion does not hold under the RBAC suite. Carried forward for the release-certification phase; no market conduct object depends on it.',true,true,'platform_security','MC-10','MC-12','Re-run rbac/100_prudential_rls in full and confirm assertion 22 passes with no widened grants.'),
('RD-002','rbac/110_fit_and_proper_rls','23','Fit and proper record visibility assertion fails','DATA_API_GRANT','A fit and proper visibility assertion does not hold. Sensitive personal data path, so treated as security blocking.',true,true,'platform_security','MC-10','MC-12','Re-run rbac/110_fit_and_proper_rls and confirm assertion 23 passes for every external persona.'),
('RD-003','rbac/10_permission_dependencies','7','Permission dependency closure assertion fails','PERMISSION_DEPENDENCY','A declared permission dependency is not satisfied in the permission graph. Does not grant additional access, but weakens the dependency guarantee.',false,true,'platform_security','MC-10','MC-12','Re-run rbac/10_permission_dependencies and confirm the dependency closure holds for all modules.'),
('RD-004','rbac/130_critical_rpc_hardening','32','Critical RPC hardening assertion fails','RPC_HARDENING','One legacy remote operation is not hardened to the current standard. Outside the market conduct call surface.',true,true,'platform_security','MC-10','MC-12','Re-run rbac/130_critical_rpc_hardening and confirm assertion 32 passes after the operation is gated.'),
('RD-005','rbac/150_storage_policy_hardening','7','Storage policy hardening assertion fails','STORAGE_POLICY','A document storage policy assertion does not hold. Evidence confidentiality is affected, so treated as security blocking.',true,true,'platform_security','MC-10','MC-12','Re-run rbac/150_storage_policy_hardening and confirm assertion 7 passes for every bucket path.'),
('RD-006','rbac/295_workflow_step_authorization','2','Workflow step authorisation assertion 2 fails','WORKFLOW_AUDIT','A workflow step authorisation assertion does not hold for a legacy approval path.',false,true,'workflow_owner','MC-10','MC-12','Re-run rbac/295_workflow_step_authorization and confirm assertion 2 passes.'),
('RD-007','rbac/295_workflow_step_authorization','3','Workflow step authorisation assertion 3 fails','WORKFLOW_AUDIT','A second workflow step authorisation assertion does not hold for the same legacy approval path.',false,true,'workflow_owner','MC-10','MC-12','Re-run rbac/295_workflow_step_authorization and confirm assertion 3 passes.'),
('RD-008','rbac/90_approval_workflows_rls',NULL,'Approval workflow visibility suite fails','DATA_API_GRANT','The approval workflow visibility suite does not pass end to end. Carried forward; market conduct approvals use their own governed operations.',false,true,'workflow_owner','MC-10','MC-12','Re-run rbac/90_approval_workflows_rls in full and confirm every assertion passes.')
